"""Git-backed state store for the personal assistant.

The state repo is a separate git repository that holds JSON snapshots
of external system state (calendar, Jira, GitHub). Collectors write
data here; analyzers read diffs to detect changes.
"""

import logging
import subprocess
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path

logger = logging.getLogger(__name__)

# Directories created during init
_STATE_DIRS = [
    "calendar",
    "jira/snapshots",
    "github/prs",
    "config",
    "digests",
]

DEFAULT_STATE_PATH = Path.home() / ".local" / "share" / "pa-state"


@dataclass(frozen=True)
class FileChange:
    """A single file change detected in the state repo."""

    path: str
    change_type: str  # "added", "modified", "deleted", "untracked"


class StateRepoError(Exception):
    """Raised when a state repo operation fails."""


def _run_git(
    repo_path: Path,
    *args: str,
    check: bool = True,
) -> subprocess.CompletedProcess[str]:
    """Run a git command in the state repo."""
    cmd = ["git", "-C", str(repo_path), *args]
    logger.debug("Running: %s", " ".join(cmd))
    return subprocess.run(
        cmd,
        capture_output=True,
        text=True,
        check=check,
    )


def init_repo(*, path: Path = DEFAULT_STATE_PATH) -> Path:
    """Initialize the state repo and directory structure.

    Creates the git repository and subdirectories if they don't exist.
    Safe to call on an already-initialized repo.

    Returns the repo path.
    """
    path.mkdir(parents=True, exist_ok=True)

    git_dir = path / ".git"
    if not git_dir.exists():
        _run_git(path, "init")
        logger.info("Initialized state repo at %s", path)

    for subdir in _STATE_DIRS:
        (path / subdir).mkdir(parents=True, exist_ok=True)
        gitkeep = path / subdir / ".gitkeep"
        if not gitkeep.exists():
            gitkeep.touch()

    # Initial commit if repo is empty
    result = _run_git(path, "rev-parse", "HEAD", check=False)
    if result.returncode != 0:
        _run_git(path, "add", ".")
        _run_git(path, "commit", "-m", "Initialize state repo")
        logger.info("Created initial commit")

    return path


def get_changes(*, repo_path: Path = DEFAULT_STATE_PATH) -> list[FileChange]:
    """Get all changes since the last commit.

    Returns both staged/unstaged modifications and untracked files.
    """
    _assert_repo_exists(repo_path)
    changes: list[FileChange] = []

    # Tracked file changes (staged + unstaged) against HEAD
    result = _run_git(repo_path, "diff", "HEAD", "--name-status", check=False)
    if result.returncode == 0:
        for line in result.stdout.strip().splitlines():
            if not line:
                continue
            parts = line.split("\t", 1)
            if len(parts) != 2:
                continue
            status_code, filepath = parts
            change_type = _git_status_to_change_type(status_code)
            changes.append(FileChange(path=filepath, change_type=change_type))

    # Untracked files
    result = _run_git(repo_path, "ls-files", "--others", "--exclude-standard")
    for line in result.stdout.strip().splitlines():
        if line:
            changes.append(FileChange(path=line, change_type="untracked"))

    return changes


def commit_state(
    message: str,
    *,
    repo_path: Path = DEFAULT_STATE_PATH,
) -> bool:
    """Stage all changes and commit.

    Returns True if a commit was created, False if nothing to commit.
    """
    _assert_repo_exists(repo_path)

    _run_git(repo_path, "add", ".")
    result = _run_git(repo_path, "diff", "--cached", "--quiet", check=False)
    if result.returncode == 0:
        logger.info("Nothing to commit")
        return False

    _run_git(repo_path, "commit", "-m", message)
    logger.info("Committed: %s", message)
    return True


def get_last_commit_time(
    *,
    repo_path: Path = DEFAULT_STATE_PATH,
) -> datetime | None:
    """Get the timestamp of the most recent commit.

    Returns None if the repo has no commits.
    """
    _assert_repo_exists(repo_path)
    result = _run_git(
        repo_path,
        "log",
        "-1",
        "--format=%aI",
        check=False,
    )
    if result.returncode != 0 or not result.stdout.strip():
        return None
    return datetime.fromisoformat(result.stdout.strip())


def get_file_at_last_commit(
    filepath: str,
    *,
    repo_path: Path = DEFAULT_STATE_PATH,
) -> str | None:
    """Read a file's content from the last commit (HEAD).

    Returns None if the file doesn't exist in HEAD.
    """
    _assert_repo_exists(repo_path)
    result = _run_git(
        repo_path,
        "show",
        f"HEAD:{filepath}",
        check=False,
    )
    if result.returncode != 0:
        return None
    return result.stdout


def status_summary(
    *,
    repo_path: Path = DEFAULT_STATE_PATH,
) -> str:
    """Return a human-readable status summary of the state repo."""
    _assert_repo_exists(repo_path)

    changes = get_changes(repo_path=repo_path)
    last_commit = get_last_commit_time(repo_path=repo_path)

    lines = [f"State repo: {repo_path}"]
    if last_commit:
        lines.append(f"Last commit: {last_commit.isoformat()}")
    else:
        lines.append("Last commit: (none)")

    if not changes:
        lines.append("No uncommitted changes")
    else:
        lines.append(f"{len(changes)} uncommitted change(s):")
        for change in changes:
            lines.append(f"  {change.change_type:10s} {change.path}")

    return "\n".join(lines)


def _assert_repo_exists(repo_path: Path) -> None:
    """Raise StateRepoError if the repo doesn't exist."""
    if not (repo_path / ".git").exists():
        raise StateRepoError(
            f"State repo not found at {repo_path}. " "Run 'pa state init' first."
        )


def _git_status_to_change_type(status_code: str) -> str:
    """Convert git diff --name-status code to a human-readable type."""
    mapping = {
        "A": "added",
        "M": "modified",
        "D": "deleted",
        "R": "renamed",
        "C": "copied",
    }
    return mapping.get(status_code[0], "modified")
